import sys
from collections import deque

data = sys.stdin.read().split()
start = tuple(int(x) for x in data[:9])
goal = (1,) * 9
adj = []
for c in range(9):
    r, k = divmod(c, 3)
    nb = []
    for dr, dk in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nk = r + dr, k + dk
        if 0 <= nr < 3 and 0 <= nk < 3:
            nb.append(nr * 3 + nk)
    adj.append(nb)
dist = {start: 0}
dq = deque([start])
while dq:
    s = dq.popleft()
    if s == goal:
        break
    for c in range(9):
        if s[c] > 0:
            for d in adj[c]:
                t = list(s)
                t[c] -= 1
                t[d] += 1
                t = tuple(t)
                if t not in dist:
                    dist[t] = dist[s] + 1
                    dq.append(t)
print(dist[goal])

