    def fmt(c):
        return '\n'.join(' '.join(map(str, c[3 * i:3 * i + 3])) for i in range(3))
    tests = [fmt([1] * 9)]
    for pos in range(9):
        c = [0] * 9
        c[pos] = 9
        tests.append(fmt(c))
    tests.append(fmt([3, 0, 0, 0, 3, 0, 0, 0, 3]))
    tests.append(fmt([1, 1, 0, 1, 1, 1, 1, 1, 2]))
    tests.append(fmt([2, 0, 2, 0, 1, 0, 2, 0, 2]))
    tests.append(fmt([0, 4, 0, 4, 1, 0, 0, 0, 0]))
    for _ in range(40):
        mode = rng.randint(0, 2)
        c = [0] * 9
        if mode == 0:
            for _ in range(9):
                c[rng.randrange(9)] += 1
        elif mode == 1:
            cells = rng.sample(range(9), rng.randint(1, 3))
            for _ in range(9):
                c[rng.choice(cells)] += 1
        else:
            c = [1] * 9
            for _ in range(rng.randint(1, 6)):
                a = rng.randrange(9)
                b = rng.randrange(9)
                if c[a] > 0:
                    c[a] -= 1
                    c[b] += 1
        tests.append(fmt(c))
    return tests

